#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin>>N;
    vector<double> x(N),y(N);
    for(int i=0;i<N;i++) cin>>x[i]>>y[i];

    vector<bool> is_prime(N,false);
    {
        vector<bool> sieve(N,true);
        if(N>0) sieve[0]=false;
        if(N>1) sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i])
                for(int j=i*i;j<N;j+=i) sieve[j]=false;
        is_prime=sieve;
    }

    auto dist=[&](int a,int b)->double{
        double dx=x[a]-x[b],dy=y[a]-y[b];
        return sqrt(dx*dx+dy*dy);
    };

    // step s (1-indexed): edge from tour[s-1] to tour[s]
    // penalty if s%10==0 and tour[s-1] is not prime-indexed
    auto edgeCost=[&](int from,int to,int step)->double{
        double d=dist(from,to);
        if(step%10==0 && !is_prime[from]) d*=1.1;
        return d;
    };

    // Nearest neighbor
    vector<int> tour(N+1);
    {
        tour[0]=0;
        vector<bool> vis(N,false);
        vis[0]=true;
        for(int i=1;i<N;i++){
            int last=tour[i-1];
            int best=-1;double bd=1e18;
            for(int j=0;j<N;j++){
                if(!vis[j]){
                    double d=dist(last,j);
                    if(d<bd){bd=d;best=j;}
                }
            }
            tour[i]=best;
            vis[best]=true;
        }
        tour[N]=0;
    }

    auto segCost=[&](const vector<int>&t,int from,int to)->double{
        double c=0;
        for(int s=from;s<=to;s++) c+=edgeCost(t[s-1],t[s],s);
        return c;
    };

    double totalCost=segCost(tour,1,N);

    auto startTime=chrono::steady_clock::now();
    auto elapsed=[&]()->double{
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    mt19937 rng(42);
    double T=totalCost*0.02;
    double Tend=totalCost*0.0001;
    double timeLimit=9.0;

    long long iter=0;
    while(elapsed()<timeLimit){
        double frac=elapsed()/timeLimit;
        double temp=T*pow(Tend/T,frac);

        int i=1+(rng()%(N-1));
        int j=i+1+(rng()%min(N-i,300));
        if(j>N) j=N;
        if(i>=j) continue;

        int lo=i,hi=min(j+1,N);
        double oldC=segCost(tour,lo,hi);

        reverse(tour.begin()+i,tour.begin()+j+1);

        double newC=segCost(tour,lo,hi);
        double delta=newC-oldC;

        if(delta<0 || (temp>1e-15 && exp(-delta/temp)>(rng()%1000000)/1000000.0)){
            totalCost+=delta;
        } else {
            reverse(tour.begin()+i,tour.begin()+j+1);
        }
        iter++;
    }

    cout<<N+1<<"\n";
    for(int i=0;i<=N;i++) cout<<tour[i]<<"\n";
}
